cd /work && python3 - <<'PY'
from math import comb
def fisher(a,b,c,d):
    n=a+b+c+d; r1=a+b; r2=c+d; c1=a+c; c2=b+d
    def p(x):
        return comb(r1,x)*comb(r2,c1-x)/comb(n,c1)
    obs=p(a)
    lo=max(0,c1-r2); hi=min(r1,c1)
    return sum(p(x) for x in range(lo,hi+1) if p(x)<=obs+1e-12)
for t in [(4,0,2,2),(2,0,2,2),(4,0,3,1),(3,1,2,2)]:
    print(t, round(fisher(*t),4))
PY

